UPDATE kinguin_product_suggestions SET platform = CASE store WHEN 'Steam' THEN 'PC' WHEN 'EA App' THEN 'PC' WHEN 'Epic Games' THEN 'PC' WHEN 'GOG' THEN 'PC' WHEN 'Battle.net' THEN 'PC' WHEN 'Rockstar' THEN 'PC' WHEN 'Windows Store' THEN 'PC' WHEN 'Ubisoft Connect' THEN 'PC' WHEN 'Nintendo' THEN 'Nintendo' WHEN 'Xbox' THEN 'Xbox' WHEN 'PlayStation' THEN 'PlayStation' ELSE 'PC' END WHERE store IS NOT NULL AND (platform IS NULL OR platform = store);